      "basis": "author_reported",
      "evidence_locator_ids": [
        "S03-E05"
      ],
      "statement": "Isotherm (batch) tests do not directly evaluate adsorption breakthrough in GAC columns; modeling tools (e.g., Adsorption Design Software) are required to relate isotherm parameters to full- or pilot-scale breakthrough performance."
    },
    {
      "basis": "author_reported",
      "evidence_locator_ids": [
        "S03-E05"
      ],
      "statement": "Isotherm parameters obtained with ground GAC may need adjustment when used to design or model full- or pilot-scale GAC systems with larger particle sizes, due to particle-size impacts on adsorption behavior and kinetics."
    },
    {
      "basis": "author_reported",
      "evidence_locator_ids": [
        "S03-E02",
        "S03-E07"
      ],
      "statement": "Ideal adsorbed solution theory (IAST) performed poorly for PFAS mixtures, with and without NOM, and may be insensitive when modeling trace constituents like PFAS; using IAST as currently implemented can therefore lead to errors in predicting GAC performance from batch data."
    },
    {
      "basis": "author_reported",
      "evidence_locator_ids": [
        "S03-E05",
        "S03-E07"
      ],
      "statement": "The study focused on impacts of NOM and major ions and did not investigate competition with non-PFAS adsorbable synthetic organic compounds; additional background species and kinetics in columns were not explored."
